// Retry thu cong: chi cho method idempotent, CO tran so lan thu + backoff kem jitter
static final Set<Integer> RETRYABLE = Set.of(408, 429, 502, 503, 504);
static final int MAX_ATTEMPTS = 3;

HttpResponse<String> sendWithRetry(HttpRequest req) throws IOException, InterruptedException {
    for (int attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {   // LUON co tran, khong while(true)
        final int n = attempt;
        long waitMs;
        try {
            HttpResponse<String> res = CLIENT.send(req, HttpResponse.BodyHandlers.ofString());
            if (!RETRYABLE.contains(res.statusCode())) return res;  // 500/501/505 KHONG retry
            if (attempt == MAX_ATTEMPTS) return res;                // het luot: tra ve nguyen trang
            waitMs = res.headers().firstValue("Retry-After")        // ton trong Retry-After
                       .map(v -> parseRetryAfterMillis(v))
                       .orElseGet(() -> backoffWithJitter(n));
        } catch (IOException e) {
            if (attempt == MAX_ATTEMPTS) throw e;
            waitMs = backoffWithJitter(n);
        }
        Thread.sleep(waitMs);
    }
    throw new IllegalStateException("khong the toi day");
}

long backoffWithJitter(int attempt) {
    long base = (long) (100 * Math.pow(2, attempt - 1));           // 100, 200, 400 ms
    return base / 2 + ThreadLocalRandom.current().nextLong(base);  // jitter quanh base
}

Long parseRetryAfterMillis(String v) {   // tra null neu la HTTP-date -> Optional.map thanh empty
    try { return Long.parseLong(v.trim()) * 1000; } catch (NumberFormatException e) { return null; }
}

// 1) Enum - an toan nhat, chong ca serialization lan reflection
public enum ConfigStore {
    INSTANCE;
    private final Map<String, String> data = new ConcurrentHashMap<>();
    public String get(String k) { return data.get(k); }
}

// 2) Holder idiom - lazy that su, khong khoa trong code cua ban
public final class ConfigStore2 {
    private ConfigStore2() {}
    private static class Holder {
        static final ConfigStore2 INSTANCE = new ConfigStore2();
    }
    public static ConfigStore2 getInstance() { return Holder.INSTANCE; }
}

// 3) DCL - BAT BUOC volatile, thieu la bug canh tranh
public final class ConfigStore3 {
    private static volatile ConfigStore3 instance;   // bo volatile = bug
    private ConfigStore3() {}
    public static ConfigStore3 getInstance() {
        ConfigStore3 local = instance;               // doc volatile 1 lan
        if (local == null) {
            synchronized (ConfigStore3.class) {
                local = instance;
                if (local == null) {
                    instance = local = new ConfigStore3();
                }
            }
        }
        return local;
    }
}

