// Builder cho object nhieu truong tuy chon, giu tinh bat bien
public final class SearchQuery {
    private final String keyword;     // bat buoc
    private final int page;
    private final int size;
    private final String sortBy;

    private SearchQuery(Builder b) {  // copy tu builder, khong giu tham chieu
        this.keyword = b.keyword;
        this.page = b.page;
        this.size = b.size;
        this.sortBy = b.sortBy;
    }

    public static Builder builder(String keyword) { return new Builder(keyword); }

    public static final class Builder {
        private final String keyword;
        private int page = 0;
        private int size = 20;
        private String sortBy = "id";

        private Builder(String keyword) {                 // ep tham so bat buoc
            this.keyword = Objects.requireNonNull(keyword);
        }
        public Builder page(int page) { this.page = page; return this; }
        public Builder size(int size) { this.size = size; return this; }
        public Builder sortBy(String s) { this.sortBy = s; return this; }

        public SearchQuery build() {                      // validate lien truong o day
            if (size <= 0 || size > 100) throw new IllegalArgumentException("size 1..100");
            return new SearchQuery(this);
        }
    }
}

